import dis, sys
import pybamm
from pybamm.expression_tree.binary_operators import add

tracked={'l_left','l_right','left','left_dim_size','new_left','new_sum','out','r_left','right','right_dim_size'}
instr_map={ins.offset:ins for ins in dis.get_instructions(add)}
records=[]

def tracer(frame,event,arg):
    if frame.f_code is add.__code__:
        if event=='call':
            frame.f_trace_opcodes=True
            return tracer
        if event=='opcode':
            ins=instr_map[frame.f_lasti]
            if ins.argval in tracked and ('LOAD' in ins.opname or 'STORE' in ins.opname):
                records.append((frame.f_lineno, ins.opname, ins.argval, frame.f_lasti))
    return tracer

sys.settrace(tracer)
_ = pybamm.Variable('a') + pybamm.Variable('b')
sys.settrace(None)
for r in records:
    print(r)
